pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 ticket, uint256 fee) internal {
        ticket = bound(ticket, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(ticket >= fee && fee > 0);
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        try c.play{value: ticket}() {} catch { return; }
        uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        assertTrue(!(random == 1 && potBefore == 0 && potAfter == 0 && ticket >= fee));
    }

    function testFuzz_run(uint256 ticket, uint256 fee) public {
        _run(ticket, fee);
    }

    receive() external payable {}
}
